response:
import { prisma } from '@/lib/prisma';
import Link from 'next/link';

export default async function PostsPage({ searchParams }) {
  const { page } = await searchParams;
  const current = Math.max(1, Number(page) || 1);
  const perPage = 10;
  const [posts, total] = await Promise.all([
    prisma.post.findMany({
      skip: (current - 1) * perPage,
      take: perPage,
      orderBy: { createdAt: 'desc' },
    }),
    prisma.post.count(),
  ]);
  const totalPages = Math.ceil(total / perPage);
  return (
    <div>
      {posts.map((p) => (
        <Link key={p.id} href={`/posts/${p.slug}`}>{p.title}</Link>
      ))}
      <div>
        {current > 1 && <Link href={`?page=${current - 1}`}>Trước</Link>}
        Trang {current}/{totalPages}
        {current < totalPages && <Link href={`?page=${current + 1}`}>Sau</Link>}
      </div>
    </div>
  );
}
Lưu ý: searchParams là Promise trong App Router, phải await trước khi dùng.

Dùng auth() export từ auth.ts (NextAuth v5) trong middleware. Tạo middleware.ts ở root:
import NextAuth from 'next-auth';
import { authConfig } from './auth.config';

export default NextAuth(authConfig).auth((req) => {
  const isLoggedIn = !!req.auth;
  const { pathname } = req.nextUrl;
  const isProtected = ['/dashboard', '/admin'].some((p) => pathname.startsWith(p));
  if (!isLoggedIn && isProtected) {
    const url = new URL('/login', req.nextUrl);
    url.searchParams.set('callbackUrl', pathname);
    return Response.redirect(url);
  }
  return NextResponse.next();
});

export const config = { matcher: ['/dashboard/:path*', '/admin/:path*'] };
Lưu ý: middleware chạy ở edge nên chỉ verify JWT, không đọc session từ database. Giữ secret trong env, không hardcode.

type NonEmpty<T> = {
  [K in keyof T]: T[K] extends null | undefined | '' ? never : K;
}[keyof T];

function compactObject<T extends Record<string, unknown>>(obj: T): Pick<T, NonEmpty<T>> {
  return Object.fromEntries(
    Object.entries(obj).filter(([, v]) => v !== null && v !== undefined && v !== '')
  ) as Pick<T, NonEmpty<T>>;
}

const cleaned = compactObject({ name: 'An', age: 0, bio: '', nick: null });
// cleaned: { name: 'An', age: 0 }
Lưu ý: 0 giữ nguyên vì khác '' và null. Muốn bỏ cả 0 và false thì mở rộng predicate. Mapped type NonEmpty đảm bảo key bị bỏ cũng biến mất khỏi type.

model User {
  id        String   @id @default(cuid())
  email     String   @unique
  roles     UserRole[]
  createdAt DateTime @default(now())
}

model Role {
  id    String     @id @default(cuid())
  name  String     @unique
  users UserRole[]
}

model UserRole {
  userId     String
  roleId     String
  user       User   @relation(fields: [userId], references: [id], onDelete: Cascade)
  role       Role   @relation(fields: [roleId], references: [id], onDelete: Cascade)
  assignedAt DateTime @default(now())
  @@id([userId, roleId])
}
Dùng bảng join UserRole rõ ràng thay vì implicit relation để chứa metadata như assignedAt. Truy vấn: prisma.user.findUnique({ where: { id }, include: { roles: { include: { role: true } } } }). Chạy npx prisma migrate dev để sinh bảng.

// server/auth.ts
import { initTRPC, TRPCError } from '@trpc/server';

export const t = initTRPC.context().create();

export const isAuthed = t.middleware(({ ctx, next }) => {
  if (!ctx.user) {
    throw new TRPCError({ code: 'UNAUTHORIZED' });
  }
  return next({ ctx: { user: ctx.user } });
});

export const protectedProcedure = t.procedure.use(isAuthed);

// server/router/user.ts
export const userRouter = t.router({
  me: protectedProcedure.query(async ({ ctx }) => ctx.user),
});
Cách này gọn vì check auth nằm ở middleware, procedure chỉ dùng ctx.user. Nhớ nhét user vào context từ resolver (đọc cookie session) mỗi request.

import { create } from 'zustand';
import { persist } from 'zustand/middleware';

interface CartState {
  items: { id: string; qty: number }[];
  add: (id: string) => void;
}

export const useCart = create<CartState>()(
  persist(
    (set) => ({
      items: [],
      add: (id) =>
        set((s) => ({
          items: s.items.some((i) => i.id === id)
            ? s.items.map((i) => (i.id === id ? { ...i, qty: i.qty + 1 } : i))
            : [...s.items, { id, qty: 1 }],
        })),
    }),
    { name: 'cart-storage', partialize: (s) => ({ items: s.items }) }
  )
);
partialize giới hạn chỉ lưu dữ liệu, không lưu function. Với app có SSR, tạo store mới bên trong useRef để tránh dùng chung state giữa các request, và chỉ đọc localStorage ở client.

'use client';
import { cacheExchange, fetchExchange, createClient, ssrExchange } from '@urql/core';
import { Provider } from 'urql';

const isServer = typeof window === 'undefined';
const ssr = ssrExchange({ isClient: !isServer });

const client = createClient({
  url: process.env.NEXT_PUBLIC_API_URL!,
  exchanges: [cacheExchange, ssr, fetchExchange],
});

export function Providers({ children }) {
  return <Provider value={client}>{children}</Provider>;
}
Trong Server Component dùng client mới cho mỗi request (ssrExchange isClient: false), gọi query, lấy data truyền xuống Client Component; bọc app trong Providers. urql không lấy data server-side tự động — phải tự gọi query ở server rồi hydrate qua ssrExchange, sau đó client render tiếp mà không gọi lại API.

Zod là cách chuẩn để validate input tRPC, type tự suy từ schema:
import { z } from 'zod';

const createPostSchema = z.object({
  title: z.string().min(1).max(120),
  content: z.string().min(10),
  tags: z.array(z.string()).max(5).default([]),
});

export const postRouter = t.router({
  create: publicProcedure
    .input(createPostSchema)
    .mutation(async ({ ctx, input }) => {
      return ctx.prisma.post.create({ data: input });
    }),
});
Client tự có type của input, sai field hay sai kiểu báo ngay lúc gọi. Muốn tự sinh form validation thì tái sử dụng cùng schema ở client. Error message tiếng Việt: đặt message trong từng refine hoặc dùng zodErrorMap toàn cục.

export function middleware(req: NextRequest) {
  const token = req.cookies.get('session')?.value;
  const isLoginPage = req.nextUrl.pathname === '/login';

  if (!token && !isLoginPage && req.nextUrl.pathname.startsWith('/account')) {
    const url = new URL('/login', req.nextUrl);
    url.searchParams.set('from', req.nextUrl.pathname);
    return NextResponse.redirect(url);
  }

  if (token && isLoginPage) {
    return NextResponse.redirect(new URL('/account', req.nextUrl));
  }

  return NextResponse.next();
}

export const config = {
  matcher: ['/account/:path*', '/login'],
};
Nhớ: middleware chạy ở edge nên không đọc DB — chỉ verify cookie/token nhẹ. Redirect kèm param 'from' để sau khi login quay lại trang gốc. Nếu đã dùng NextAuth thì bọc bằng NextAuth(authConfig).auth để có req.auth.

Vì SSR render trên server không có window, dùng trực tiếp sẽ lỗi ReferenceError. Ba cách tùy tình huống: (1) Nếu component chạy client thuần, thêm 'use client' và đọc window trong useEffect:
const [mounted, setMounted] = useState(false);
useEffect(() => setMounted(true), []);
if (!mounted) return <div className=""h-screen""></div>;
return <Chart width={window.innerWidth} />;
(2) Dùng dynamic() với ssr: false để import lazy chỉ ở client: const Chart = dynamic(() => import('./Chart'), { ssr: false });. (3) Truyền dữ liệu từ Server Component xuống, client chỉ render khi prop chắc chắn. Cách 1 chuẩn nhất để tránh hydration mismatch.

Closure là hàm con vẫn 'nhớ' các biến trong scope của hàm cha ngay cả khi hàm cha đã kết thúc. Mỗi khi một hàm được định nghĩa, nó giữ lại reference tới lexical environment nơi nó sinh ra. Ví dụ:

function makeCounter() {
  let count = 0;
  return function() {
    count += 1;
    return count;
  };
}
const counter = makeCounter();
counter(); // 1
counter(); // 2

Biến count không bị thu hồi sau khi makeCounter kết thúc vì closure vẫn trỏ tới nó. Closure hữu ích để tạo private state, factory function, và trong vòng lặp cần bẫy giá trị của biến (trước khi có let). Cũng chính là cơ chế khiến biến var trong setTimeout bên vòng for gây lỗi kinh điển.

async/await là cú pháp giúp làm việc với Promise dễ đọc hơn so với chuỗi .then(). Một hàm khai báo async luôn trả về Promise; bên trong nó, từ khoá await tạm dừng hàm chờ một Promise settle rồi trả về giá trị resolved, và nếu reject thì ném exception bắt bằng try/catch. Ví dụ:

async function loadUser(id) {
  const res = await fetch(`/api/users/${id}`);
  if (!res.ok) throw new Error('Lỗi mạng');
  const data = await res.json();
  return data;
}

Nên dùng cho mọi thao tác bất đồng bộ: gọi API, đọc file, truy vấn database. Tránh await tuần tự khi các yêu cầu độc lập với nhau — lúc đó dùng Promise.all để chạy song song cho nhanh. Không được quên try/catch hoặc .catch vì lỗi bị nuốt sẽ gây bug khó dò.

useEffect chạy sau khi component render xong. Đặt phép đối chiếu: componentDidMount tương đương effect với mảng deps rỗng `[]`, componentDidUpdate tương đương effect không có deps hoặc có deps thay đổi, componentWillUnmount tương đương cleanup trả về trong effect.

```js
useEffect(() => {
  const timer = setInterval(loadData, 5000)
  return () => clearInterval(timer) // unmount
}, []) // mount
```

Nếu thêm biến vào `[]` thì effect chạy lại mỗi khi biến đó đổi. Lưu ý: effect luôn chạy ít nhất một lần sau lần render đầu.

ref dùng cho giá trị đơn lẻ (số, chuỗi, boolean) và lúc nào cũng cần `.value` khi truy cập trong script; reactive dùng cho object/array và truy cập trực tiếp không cần `.value`. Quy tắc thực dụng: gần như lúc nào cũng dùng ref cho đơn giản, dùng reactive khi muốn gộp nhiều trường form thành một object có cấu trúc:

```js
const ten = ref('')
const form = reactive({ ten: '', sdt: '', diaChi: '' })
```

Trong template thì ref tự bỏ `.value` nên không cần lo. Tránh reactive cho object bạn gán lại toàn bộ vì mất reactivity.

Closure là hàm con giữ lại được biến của phạm vi cha ngay cả sau khi hàm cha đã chạy xong. Thực tế hay dùng để: 1) tạo biến private (hàm đếm, bộ nhớ cache nội bộ), 2) tạo hàm đóng gói cấu hình sẵn (function factory), 3) xử lý sự kiện nhớ biến vòng lặp. Ví dụ cache:

```js
function taoCache() {
  const luu = {}
  return (key, val) => { if (val) luu[key] = val; return luu[key] }
}
```

Khi nào cần: khi bạn muốn một hàm mang theo dữ liệu riêng mà không làm ô nhiễm scope toàn cục.

async/await ưu tiên cho hầu hết trường hợp vì code chạy tuần tự đọc như code đồng bộ, dễ gỡ lỗi, kết hợp try/catch gọn. .then vẫn hữu dụng khi bạn muốn chạy song song các promise rồi gộp bằng Promise.all, hoặc xử lý phản hồi ngắn không cần nhiều bước. Ví dụ nối tiếp:

```js
async function xuLyDon(donId) {
  const don = await api.get(`/don/${donId}`)
  const khach = await api.get(`/khach/${don.khachId}`)
  return { don, khach }
}
```

Muốn chạy song song thì `const [a, b] = await Promise.all([api.get(x), api.get(y)])`.

Express cho phép viết middleware xử lý lỗi với 4 tham số `(err, req, res, next)` đặt sau tất cả route, và các handler có thể trả `next(err)` để ném lỗi về trung tâm. Viết wrapper để bắt lỗi async:

```js
const bat = fn => (req, res, next) =>
  Promise.resolve(fn(req, res, next)).catch(next)

app.get('/don/:id', bat(async (req, res) => {
  const don = await Don.findById(req.params.id)
  if (!don) { const e = new Error('Khong tim thay'); e.status = 404; throw e }
  res.json(don)
}))

app.use((err, req, res, next) => {
  res.status(err.status || 500).json({ loi: err.message })
})
```

Như vậy bỏ hết try/catch lặp ở từng route.

Index giống mục lục sách: MySQL quét nhanh theo cột được đánh index thay vì dò cả bảng. Đánh index cho cột xuất hiện trong WHERE, JOIN và ORDER BY, nhất là cột lọc nhiều như `trang_thai`, `khach_id`, `ngay_tao`. Cú pháp:

```sql
CREATE INDEX idx_trang_thai ON don_hang (trang_thai);
CREATE INDEX idx_khach_ngay ON don_hang (khach_id, ngay_tao);
```

Với index ghép nhớ để cột lọc chính xác trước. Chạy `EXPLAIN SELECT ...` để xem MySQL có dùng index không (cột `type` hiện `ref`/`range` thay vì `ALL`). Đừng đánh index tràn lan vì mỗi index làm chậm INSERT/UPDATE.

MySQL FULLTEXT index nhanh hơn LIKE nhiều, nhưng mặc định không tách từ tiếng Việt tốt vì tiếng Việt có dấu và không có khoảng trắng phân tách từ như tiếng Anh. Hai hướng: 1) lưu thêm cột chuẩn hóa bỏ dấu (lowercase, strip dấu) và fulltext trên cột đó, người dùng gõ có dấu thì bỏ dấu truy vấn trước khi tìm; 2) tích hợp bộ tách từ tiếng Việt (như underthesea, VnCoreNLP) khi đánh index. Với MySQL:

```sql
ALTER TABLE san_pham ADD FULLTEXT(ten_san_pham);
SELECT * FROM san_pham WHERE MATCH(ten_san_pham) AGAINST ('+áo +sơ +mi' IN BOOLEAN MODE);
```

Nếu cần tìm kiếm nặng hơn nữa thì cân nhắc Meilisearch hoặc Elasticsearch.

utf8 trong MySQL thực chất chỉ là utf8mb3, không đủ cho một số ký tự đặc biệt như emoji; nên dùng utf8mb4 cho toàn bộ. Khi lưu tiếng Việt bị hỏng thường do lệch charset ở một trong các tầng: database, bảng, cột, kết nối (connection charset) hoặc khi hiển thị trên trang. Kiểm tra lệnh:

```sql
SHOW VARIABLES LIKE 'character_set%';
ALTER DATABASE db CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
ALTER TABLE bang CONVERT TO CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
```

Và đặt `SET NAMES utf8mb4` khi kết nối. Nếu dữ liệu đã lưu hỏng thì phải sửa lại dữ liệu cũ chứ đổi charset không tự sửa được.

Do React Router xử lý route phía client, còn Nginx chỉ phục vụ file tĩnh nên khi request /gioi-thieu Nginx không tìm thấy file đó và trả 404. Cần cấu hình Nginx trả index.html cho mọi đường dẫn (fallback):

```nginx
location / {
    try_files $uri $uri/ /index.html;
}
```

Sau khi sửa chạy `nginx -t` rồi `systemctl reload nginx`. Nhớ build trước với `npm run build` và trỏ `root` tới thư mục dist. Nếu vẫn 404 thì kiểm tra đã copy file build lên đúng đường dẫn root chưa.

Nếu chỉ nhắn tin qua lại, WebSocket là chuẩn vì server đẩy tin ngay, ít tốn request hơn và không trễ. Polling bằng setInterval vài giây gọi API thì code dễ hơn nhưng trễ tin, tốn request, và khi nhiều người dùng sẽ đè server. Với WebSocket dùng Socket.IO là dễ nhất:

```js
// server
const { Server } = require('socket.io')
const io = new Server(server)
io.on('connection', s => s.on('tin_nhan', d => io.emit('tin_nhan', d)))

// client
const socket = io()
socket.emit('tin_nhan', { text: 'xin chào' })
```

Nếu ứng dụng chỉ vài người và tin không cần ngay lập tức thì polling chấp nhận được, nhưng WebSocket vẫn đáng đầu tư cho chat.

Rate limiting giới hạn số request trong một khoảng thời gian cho mỗi IP hoặc mỗi user, trả HTTP 429 khi vượt quá. Dùng thư viện express-rate-limit đơn giản:

```js
const rateLimit = require('express-rate-limit')
const gioiHan = rateLimit({
  windowMs: 60 * 1000,
  max: 60,
  message: { loi: 'Quá nhiều yêu cầu, thử lại sau 1 phút' }
})
app.use('/api', gioiHan)
```

Nên áp dụng riêng cho endpoint nhạy cảm như đăng nhập với giới hạn thấp hơn, dùng X-Forwarded-For khi chạy sau reverse proxy, và kết hợp lưu đếm bằng Redis nếu chạy nhiều instance. Nhớ trả header chứa thời gian chờ để client biết.

SSG (Static Site Generation) render HTML tại lúc build, rất nhanh và SEO tốt — dùng cho trang ít thay đổi như trang chủ, blog, danh mục. SSR render trên mỗi request — dùng khi dữ liệu cá nhân hóa hoặc thay đổi liên tục như trang chi tiết theo user, kết quả tìm kiếm. Next.js cho phép trộn cả hai trong một app:

```jsx
export async function getStaticProps() { /* SSG */ }
export async function getServerSideProps() { /* SSR */ }
```

App Router mới dùng generateStaticParams cho SSG và dynamic rendering cho SSR. Nguyên tắc: dữ liệu công khai ít đổi → SSG + revalidate; dữ liệu theo user/thời gian thực → SSR hoặc client fetch.

Phân trang phải làm phía server để không kéo cả bảng về client. Dùng query param `trang` và `gioi_han` (hoặc cursor), trả thêm metadata:

```js
const trang = Math.max(1, parseInt(req.query.trang) || 1)
const gioiHan = Math.min(50, parseInt(req.query.gioi_han) || 20)
const [rows, [{ count }]] = await db.query(
  'SELECT * FROM san_pham ORDER BY id LIMIT ? OFFSET ?',
  [gioiHan, (trang - 1) * gioiHan]
)
res.json({ du_lieu: rows, tong: count, trang, gioi_han: gioiHan })
```

Với dữ liệu thay đổi liên tục nên cân nhắc cursor pagination (dựa trên id) thay vì OFFSET vì OFFSET chậm ở trang sâu và dễ trùng lệch. Giới hạn gioi_han tối đa để tránh ai đó yêu cầu 100000 bản ghi.

nftables là thế hệ sau của Netfilter, gộp iptables/ip6tables/ebtables vào một hệ thống cú pháp, dùng in-kernel processing và tuyến chain linh hoạt hơn, debian/ubuntu mới đã nạp module nf_tables có sẵn. Cú pháp khác: không còn lệnh -A từng cái, bạn khai báo một file rule. Ví dụ tương đương hai luật iptables cơ bản:

table inet filter {
  chain input {
    type filter hook input priority 0; policy drop;
    ct state established,related accept
    iifname "lo" accept
    tcp dport 22 accept
    tcp dport {80,443} accept
  }
}

`ip family inet` gộp v4/v6. Dịch tự động có sẵn: `iptables-translate -A INPUT -s 1.2.3.4 -j DROP` chuyển một lệnh sang nft. Với máy còn dùng iptables-legacy, kiểm tra `iptables -V`; khi đã chắc nắm ai tiếp quản firewall thì nên viết mới bằng nftables và dùng `nft list ruleset` để debug thay vì duy trì hai hệ thống song song.

Bạn cài đủ hai bản php-fpm (trên ubuntu: php7.4-fpm và php8.2-fpm), chúng chạy trên các socket/port riêng. Kiểm tra: `ls /run/php/php*-fpm.sock`. Sau đó mỗi site nginx trỏ đúng socket trong block server:

server {
    listen 80;
    server_name site-cu.vn;
    root /var/www/site-cu;
    index index.php;
    location ~ \.php$ {
        fastcgi_pass unix:/run/php/php7.4-fpm.sock;
        include fastcgi_params;
        fastcgi_param SCRIPT_FILENAME $document_root$fastcgi_script_name;
    }
}

và site kia dùng unix:/run/php/php8.2-fpm.sock. Nút này phân lập version hoàn toàn, cách phục vụ pool: bạn có thể tách user riêng trên mỗi php-fpm.conf pool để site hỏng không lan nhau. Kiểm tra sau cấu hình: nginx -t && systemctl reload nginx, rồi mở file phpinfo để chắc đúng phiên bản mỗi site.

Trong OpenAI SDK mới:
from openai import OpenAI
client = OpenAI()

def chat(messages):
    stream = client.chat.completions.create(model="gpt-4o-mini", messages=messages, stream=True)
    for chunk in stream:
        delta = chunk.choices[0].delta.content
        if delta:
            yield delta

for piece in chat([{"role": "user", "content": "Xin chào"}]):
    print(piece, end="", flush=True)
Mỗi chunk có thể rỗng nên luôn kiểm tra delta.content. Phía server gom các piece lại rồi đẩy qua SSE hoặc WebSocket tới client, phía client append từng mảnh vào UI. Lưu ý: nếu dùng tool/function calling kèm stream, finish_reason và tool_calls nằm ở chunk cuối, bạn phải tích lũy toàn bộ chunk rồi mới xử lý.

API mới cho phép schema cứng:
from openai import OpenAI
import json
client = OpenAI()
resp = client.chat.completions.create(
    model="gpt-4o-mini",
    messages=[{"role": "user", "content": "Trích user và summary"}],
    response_format={
        "type": "json_schema",
        "json_schema": {
            "name": "user_info",
            "schema": {
                "type": "object",
                "properties": {"name": {"type": "string"}, "summary": {"type": "string"}},
                "required": ["name", "summary"],
            },
        },
    },
)
print(json.loads(resp.choices[0].message.content))
So với prompt ép JSON, response_format đảm bảo output là JSON hợp lệ và tuân schema đúng kiểu kể cả boolean/number, giảm hẳn lỗi parse. Hạn chế: chỉ sinh JSON thuần, không dùng kèm few-shot tự do, giá token không rẻ hơn; với response rất dài hay model rẻ, độ tuân thủ có thể giảm và lúc đó vẫn phải retry.

Tạo model Chỉ số theo tháng rồi tính trong vòng lặp, commit một lần cho nhanh:

from django.db import transaction
@transaction.atomic
def xuat_hoa_don(thang, nam):
    for p in Phong.objects.select_for_update().all():
        cs = ChiSoDienNuoc.objects.filter(phong=p, thang=thang, nam=nam).first()
        if not cs:
            continue
        tien = (cs.dien_moi - cs.dien_cu)*3500 + (cs.nuoc_moi - cs.nuoc_cu)*12000 + p.tien_phong
        HoaDon.objects.update_or_create(phong=p, thang=thang, nam=nam,
                                        defaults={'tong_tien': tien, 'trang_thai': 'CHUA_THU'})

`select_for_update` khóa bản ghi để hai nhân viên chạy song song không xuất trùng. Gọi hàm này từ command `management/commands/xuathd.py` rồi chạy cron đầu tháng là xong.

Được. Cấu hình Celery beat chạy job mỗi sáng, job đọc danh sách hợp đồng cần đóng cọc hôm nay rồi gửi qua Zalo OA API:

# tasks.py
@app.task
def nhan_tien_coc():
    hom_nay = timezone.localdate()
    hop_dongs = HopDong.objects.filter(nhan_nhac_coc=True, ngay_coc=hom_nay)
    for hd in hop_dongs:
        zalo_api.send_template(hd.khach.zalo_id, template_coc, {'hop_dong': hd.ma, 'tien': hd.tien_coc})
        hd.nhan_nhac_coc = False
        hd.save()

# settings.py
CELERY_BEAT_SCHEDULE = {
    'nhac_coc_7h': {'task': 'bds.tasks.nhan_tien_coc', 'schedule': crontab(hour=7, minute=0)}
}

Nhớ dùng `create_crontab` theo giờ server; nếu server UTC thì đặt `hour=0` để tương ứng 7h Việt Nam. Celery beat thay thế cron truyền thống, dễ theo dõi và thử lại job lỗi.

Zalo OA có cơ chế verify: lúc bạn bấm đăng ký webhook, Zalo sẽ GET kèm `mac` là chuỗi băm chuỗi `{app_id}{secret_key}{timestamp}` bằng HMAC-SHA256. Backend cần kiểm tra đúng signature ở mọi request tới:

import hashlib, hmac
class VerifyMac(MiddlewareMixin):
    def process_request(self, request):
        timestamp = request.GET.get('timestamp')
        mac = request.GET.get('mac')
        s = hmac.new(secret.encode(), f'{app_id}{secret_key}{timestamp}'.encode(), hashlib.sha256).hexdigest()
        if not hmac.compare_digest(s, mac):
            raise PermissionDenied

`hmac.compare_digest` so sánh an toàn thời gian, chống timing attack. Sau khi verify xong, tin nhắn đến nằm trong POST với JSON event; gọi `zalo.me/api/v3.0/oa/message` để trả lời. Webhook phải trả HTTP 200 nhanh, phần xử lý để Celery chạy.

Rất hợp lý ở quy mô đó. OneSignal cho phép dùng chung cho Android/iOS, trả phí theo số active user. Luồng: khách đăng ký device ID khi mở app → gửi lên server lưu bảng `Device` → khi có sự kiện gọi API:

import requests
headers = {'Authorization': f'Bearer {API_KEY}', 'Content-Type': 'application/json'}
payload = {
    'app_id': APP_ID,
    'include_player_ids': [device_id],
    'headings': {'vi': 'Đặt phòng thành công!'},
    'contents': {'vi': f'Đơn {ma_don}: check-in ngày {ngay_checkin}.'}
}
requests.post('https://api.onesignal.com/notifications', json=payload, headers=headers)

Nhắc check-in: chạy Celery beat mỗi sáng quét `ngay_checkin = ngày mai` rồi gửi. Với môi giới muốn đẩy tin mới tương tự, bạn tái sử dụng hẳn module này.

Luồng chuẩn: Gunicorn phục vụ Django trên 127.0.0.1:8000 (dùng socket), Nginx làm reverse proxy tĩnh + proxy động, Certbot cấp SSL tự gia hạn. Cấu hình Nginx:

server {
    listen 443 ssl;
    server_name cty.vn;
    location /static/ { root /srv/app/; }
    location /media/  { root /srv/app/; }
    location / {
        proxy_pass http://127.0.0.1:8000;
        proxy_set_header Host $host;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto $scheme;
    }
}

Chạy Gunicorn bằng systemd (vài worker = 2×CPU+1), `python manage.py collectstatic --noinput` trước khi restart. Certbot: `apt install certbot python3-certbot-nginx` rồi `certbot --nginx -d cty.vn`. Đừng quên tắt DEBUG trong production và dùng environment variables cho SECRET_KEY.

DRF có sẵn throttling cấu hình trong settings:

REST_FRAMEWORK = {
    'DEFAULT_THROTTLE_CLASSES': [
        'rest_framework.throttling.AnonRateThrottle',
        'rest_framework.throttling.UserRateThrottle',
    ],
    'DEFAULT_THROTTLE_RATES': {
        'anon': '60/min',
        'user': '600/hour',
    }
}

Với quy tắc riêng theo gói dịch vụ (vd bản miễn phí 1000 request/ngày), viết subclass override `get_cache_key` hoặc dùng `ScopedRateThrottle` gắn vào view. Rate limit nên đặt theo user và theo IP để bot không dùng nhiều tài khoản né. Nhớ trả header `Retry-After` để client tự chờ đúng thời gian, tránh nện tiếp.

Ngoài UniqueConstraint ở DB, thêm `select_for_update` trong transaction và đánh dấu trạng thái ngay khi bắt đầu xử lý:

@transaction.atomic
def xu_ly_dat_lich(khach_id, khung_id):
    khung = KhungGio.objects.select_for_update().filter(id=khung_id).first()
    if khung.trang_thai != 'TRONG':
        return 'Khung đã kín'
    khung.trang_thai = 'DA_DUOC_DAT'
    khung.save()
    LichXem.objects.create(khach_id=khach_id, khung=khung)

`select_for_update` khóa dòng, hai request cùng lúc vào sẽ chờ nhau, cái sau đọc được trạng thái mới và từ chối. Client cũng nên disable nút sau khi bấm. Kết hợp cả ba tầng (UI, app, DB) thì gần như không thể đặt trùng.

Thiết kế queue ghi cục bộ + đồng bộ theo thứ tự. Mô hình chuẩn: local DB (SQLite) lưu bản ghi với `dirty=1`, mỗi thao tác tạo event vào bảng `pending`. Khi có mạng, client gửi từng event kèm `client_created_at`:

# client
class GhiChu:
    id_uu = uuid4()
    noi_dung = '...'
    dirty = True

def dong_bo():
    for e in GhiChu.objects.filter(dirty=True):
        r = api.post('/sync/ghichu', json=e)
        if r.status_code == 200:
            e.dirty = False; e.save()

Server nhận kèm idempotency key là `id_uu` để request trùng không tạo bản ghi đúp. Xung đột khi cả hai sửa cùng ghi chú: ưu tiên bản `updated_at` mới hơn. Dùng gói như `watermelondb`/`rxdb` nếu không muốn tự viết phần đồng bộ.

reCAPTCHA v3 chạy ngầm, không hiện checkbox, chấm điểm 0–1 cho mỗi request. Dùng thư viện `django-recaptcha` hoặc tự gọi API verify:

import requests
def verify_captcha(token):
    r = requests.post('https://www.google.com/recaptcha/api/siteverify',
                      data={'secret': SECRET_KEY, 'response': token})
    return r.json()

# trong view khi nhận form
data = verify_captcha(request.POST['g-recaptcha-response'])
if not data.get('success') or data.get('score', 0) < 0.5:
    return JsonResponse({'error': 'Bạn có vẻ là bot'}, status=403)

Đặt site key vào template qua context processor. Nhớ thêm hidden field `g-recaptcha-response` và tải script `https://www.google.com/recaptcha/api.js?render=SITE_KEY`. Điểm thấp thì chặn hẳn; điểm trung bình cho qua nhưng thêm rate limit — giảm phiền khách thật mà vẫn chặn spam.

Celery beat phù hợp: job chạy mỗi ngày quét tin nào `cap_nhat_lan_cuoi` quá 30 ngày và còn trạng thái 'DANG_CHAO' thì chuyển sang 'CAN_CAP_NHAT':

@app.task
def danh_dau_tin_can_cap_nhat():
    moc = timezone.now() - timedelta(days=30)
    TinBDS.objects.filter(trang_thai='DANG_CHAO', cap_nhat_lan_cuoi__lt=moc)\
        .update(trang_thai='CAN_CAP_NHAT')

CELERY_BEAT_SCHEDULE = {
    'cap_nhat_trang_thai_tin': {
        'task': 'bds.tasks.danh_dau_tin_can_cap_nhat',
        'schedule': crontab(hour=1, minute=0),
    },
}

Sau đó cảnh báo môi giới qua push/email bằng job thứ hai. Trước khi chạy mass update, cân nhắc dùng `.update()` thay vì loop save() — một câu SQL cho toàn bộ, nhanh và ít xung đột. Đặt giờ chạy lúc khuya để không ảnh hưởng user đang dùng.

Dùng update với điều kiện — vừa trừ vừa kiểm tra còn đủ không, đây là cách chống oversell chuẩn nhất:

@transaction.atomic
def dat_ve(su_kien_id, sl):
    updated = SuKien.objects.filter(id=su_kien_id, con_lai__gte=sl)\
        .update(con_lai=F('con_lai') - sl)
    if not updated:
        return None  # hết vé
    return Ve.objects.create(su_kien_id=su_kien_id, sl=sl)

`filter(...).update(...)` là một câu SQL nguyên tử — hai request đồng thời không thể cùng trừ quá số còn lại vì update có điều kiện `con_lai__gte`. Kết hợp transaction để bảng Vé và trừ kho khớp nhau. Nếu về sau cần giữ chỗ tạm thời (hold ticket 15 phút) thì thêm bảng `GiuCho` với TTL.

Dùng fingerprint: chuẩn hóa tiêu đề + địa chỉ + diện tích rồi băm thành một chuỗi khóa. Nếu đã tồn tại trong khoảng thời gian gần đây thì báo nghi trùng:

import hashlib
def fingerprint(tieu_de, dia_chi, dien_tich):
    s = '|'.join([chuan_hoa(tieu_de), chuan_hoa(dia_chi), str(dien_tich)])
    return hashlib.md5(s.encode()).hexdigest()

class TinBDS(models.Model):
    fp = models.CharField(max_length=32, db_index=True)
    def save(self, *args, **kwargs):
        self.fp = fingerprint(self.tieu_de, self.dia_chi, self.dien_tich)
        super().save(*args, **kwargs)

Khi tạo tin, query `TinBDS.objects.filter(fp=fp, moi_gioi=self.moi_gioi, ngay_dang__gte=now-timedelta(days=30))`. Muốn tinh vi hơn so sánh độ tương đồng bằng `difflib.SequenceMatcher` hoặc `rapidfuzz` với ngưỡng 90%. Chỉ hiện cảnh báo chứ không chặn cứng để không làm khó môi giới đăng lại tin hợp lệ.

Được, dùng collaborative filtering kiểu item-based: tìm khách khác từng quan tâm các tin tương tự, rồi gợi ý tin họ đã xem. Đơn giản nhất với Jaccard similarity trên tập `user_id` đã xem từng tin:

from collections import defaultdict

def goi_y(khach_id, k=5):
    da_xem = set(xem_map[khach_id])
    score = defaultdict(int)
    for tin in da_xem:
        for nguoi_xem in tin_map[tin]:
            score[tin] += len(set(xem_map[nguoi_xem]) & da_xem)
    return sorted(score, key=score.get, reverse=True)[:k]

Dữ liệu nhỏ chạy tại chỗ được; lớn lên thì tính offline mỗi đêm bằng job và lưu bảng `GoiY` sẵn. Chỉ dùng hành vi người dùng, đừng dùng thông tin cá nhân nhạy cảm. Gợi ý theo 'khách hàng quan tâm dự án X cũng quan tâm dự án Y' là đủ tạo giá trị cho môi giới.
